/* popup/popup.css */
/* Opten extension popup styles — ps-popup- / ps-login- / ps- prefix */
/* v1.7 dark-only redesign — 420px, Inter font */

/* === CSS Variables: Dark-only (NO light theme) === */
:root {
  --ps-popup-bg: #171717;
  --ps-popup-header-bg: #121212;
  --ps-popup-border: #454746;
  --ps-popup-border-inner: #262626;
  --ps-popup-text: #ffffff;
  --ps-popup-muted: rgba(255, 255, 255, 0.3);
}

/* === Reset & Base === */
*, *::before, *::after {
  box-sizing: border-box;
}

body {
  width: 420px;
  margin: 0;
  padding: 0;
  background: var(--ps-popup-bg);
  color: var(--ps-popup-text);
  font-family: 'Inter', sans-serif;
  min-height: 100px;
}

/* === Screen toggle === */
.ps-popup-screen {
  display: block;
}

/* === Popup container === */
.ps-popup-container {
  position: relative;
  overflow: clip;
  min-height: 100px;
  background: var(--ps-popup-bg);
}

/* === Border overlay (RESEARCH Pattern 2) === */
.ps-popup-border-overlay {
  position: absolute;
  inset: -1px;
  border: 1px solid #454746;
  pointer-events: none;
  z-index: 10;
}

/* === Logged-out container background (Figma 3096:3814) === */
#ps-popup-logged-out {
  background: #011417;
  min-height: 512px;
  position: relative;
}

/* === Bottom wave shadow (Figma node 668:1829 — pre-blurred SVG, 670×469 with 100px blur padding) === */
/* bottom:-232.28px = -132.28px wave-bottom-offset minus 100px blur top-padding shift */
.ps-popup-bg-wrap {
  position: absolute;
  left: 50%;
  bottom: -232.28px;
  width: 670px;
  height: 469px;
  transform: translateX(-50%) translateX(11px);
  pointer-events: none;
  overflow: visible;
}

.ps-popup-bg-image {
  display: block;
  width: 100%;
  height: 100%;
}

/* === Login screen content wrapper === */
.ps-popup-content {
  display: flex;
  flex-direction: column;
  gap: 39px;
  padding: 40px;
  align-items: center;
  position: relative;
  z-index: 1;
  min-height: 512px;
}

#ps-popup-logged-out.ps-popup-logged-out--code .ps-popup-content {
  gap: 34px;
}

/* === Frame5: Logo + Text + Wave (gap 24px) === */
.ps-login-top {
  display: flex;
  flex-direction: column;
  gap: 24px;
  align-items: center;
  width: 100%;
  position: relative;
}

/* === Logo (combined icon + wordmark, single SVG 98×32 — Figma 3096:3817) === */
.ps-logo {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

.ps-logo-svg {
  width: 98px;
  height: 32px;
  display: block;
}

/* === Text block: heading + subheading (gap 16px) === */
.ps-login-text {
  display: flex;
  flex-direction: column;
  gap: 16px;
  align-items: center;
  width: 100%;
  text-align: center;
}

/* === Typography === */
.ps-login-heading {
  font-size: 24px;
  font-weight: 500;
  line-height: 1.3;
  letter-spacing: -0.96px;
  color: white;
  margin: 0;
  font-style: normal;
}

.ps-login-sub {
  font-size: 14px;
  font-weight: 400;
  line-height: 1.3;
  color: white;
  white-space: nowrap;
  margin: 0;
  font-style: normal;
}

/* === Wave decorative (LOGIN-05) === */
.ps-login-wave {
  position: absolute;
  left: 92px;
  top: 116px;
  width: 82.9px;
  height: 8.2px;
}

/* === Frame10: Button + Badges (gap 40px) === */
.ps-login-bottom {
  display: flex;
  flex-direction: column;
  gap: 32px;
  align-items: center;
  width: 270px;
}

/* === Frame11: Button + Badge1 (gap 12px) === */
.ps-login-btn-wrap {
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: center;
  width: 270px;
}

/* === Email Sign-In (Figma 3292:10 / 3293:122) === */
.ps-email-auth-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: center;
  width: 270px;
  margin: 0;
}

#ps-email-verify-form {
  width: 270px;
}

.ps-email-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 270px;
}

#ps-email-verify-form .ps-email-field {
  width: 270px;
}

.ps-email-label {
  font-size: 12px;
  font-weight: 400;
  line-height: 1.3;
  color: rgba(255, 255, 255, 0.6);
  white-space: nowrap;
}

.ps-email-label-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 270px;
}

.ps-email-change-btn {
  border: none;
  background: transparent;
  padding: 0;
  margin: 0;
  color: rgba(156, 251, 81, 0.75);
  cursor: pointer;
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  font-weight: 400;
  line-height: 1.3;
  white-space: nowrap;
}

.ps-email-change-btn:hover {
  color: #9cfb51;
}

.ps-email-change-btn:focus-visible {
  outline: 2px solid rgba(156, 251, 81, 0.5);
  outline-offset: 2px;
}

.ps-email-input {
  width: 270px;
  height: 44px;
  border: 1px solid rgba(255, 255, 255, 0.27);
  border-radius: 8px;
  background: transparent;
  padding: 0 16px;
  color: #ffffff;
  font-family: 'Inter', sans-serif;
  font-size: 12px;
  font-weight: 400;
  line-height: 1.3;
  outline: none;
}

.ps-email-input::placeholder {
  color: rgba(255, 255, 255, 0.2);
}

.ps-email-input:focus,
.ps-email-code-cell:focus {
  border-color: rgba(156, 251, 81, 0.8);
}

.ps-btn-email {
  width: 270px;
  height: 44px;
  border: none;
  border-radius: 8px;
  background: #9cfb51;
  color: #011417;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 12px 24px;
  cursor: pointer;
  font-family: 'Inter', sans-serif;
  font-size: 15px;
  font-weight: 500;
  line-height: 1.3;
}

.ps-btn-email:hover:not(:disabled) {
  background: #8ff144;
}

.ps-btn-email:focus-visible {
  outline: 2px solid rgba(255, 255, 255, 0.5);
  outline-offset: 2px;
}

.ps-btn-email:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.ps-email-code-cells {
  display: flex;
  flex-direction: row;
  gap: 8px;
  width: 270px;
  height: 44px;
}

.ps-email-code-cell {
  width: 100%;
  min-width: 0;
  flex: 1 1 0;
  height: 44px;
  border: 1px solid rgba(255, 255, 255, 0.27);
  border-radius: 8px;
  background: transparent;
  color: #ffffff;
  font-family: 'Inter', sans-serif;
  font-size: 15px;
  font-weight: 500;
  line-height: 1.3;
  text-align: center;
  outline: none;
  padding: 0;
}

/* === Google Sign-In Button (LOGIN-03) === */
.ps-btn-google {
  background: white;
  color: black;
  border: none;
  border-radius: 8px;
  padding: 11px 24px;
  width: 270px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  cursor: pointer;
  position: relative;
  font-family: 'Inter', sans-serif;
  font-size: 15px;
  font-weight: 500;
  line-height: 1.3;
  min-height: 44px;
}

.ps-btn-google[hidden] {
  display: none !important;
}

.ps-btn-google-border {
  position: absolute;
  inset: 0;
  border: 1px solid rgba(0, 0, 0, 0.1);
  border-radius: 8px;
  pointer-events: none;
}

.ps-btn-google:hover {
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

.ps-btn-google:focus-visible {
  outline: 2px solid rgba(255, 255, 255, 0.5);
  outline-offset: 2px;
}

.ps-btn-google:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.ps-btn-google-label {
  font-size: 15px;
  font-weight: 500;
  white-space: nowrap;
}

.ps-google-icon {
  width: 22px;
  height: 22px;
  flex-shrink: 0;
}

/* === Badge 1: plain (no pill background) === */
.ps-badge-plain {
  display: flex;
  gap: 8px;
  align-items: center;
}

.ps-badge-icon {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
}

.ps-badge-label {
  font-size: 12px;
  font-weight: 400;
  line-height: 1.3;
  color: rgba(255, 255, 255, 0.6);
  white-space: nowrap;
}

/* === Badges 2, 3: pill style === */
.ps-badges-pills {
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: center;
}

.ps-badge-pill {
  display: flex;
  gap: 8px;
  align-items: center;
  background: rgba(156, 251, 81, 0.05);
  padding: 4px 8px;
  border-radius: 100px;
}

.ps-badge-pill .ps-badge-label {
  color: rgba(156, 251, 81, 0.6);
}

/* === Error text === */
.ps-popup-error {
  font-size: 12px;
  color: #DC2626;
  text-align: center;
  margin: 8px 0 0 0;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

#ps-popup-logged-out .ps-popup-error {
  position: absolute;
  left: 40px;
  right: 40px;
  bottom: 12px;
  z-index: 2;
  margin: 0;
}

/* ==========================================================
   Screen B (Logged-in) — Phase 44 Dashboard
   ========================================================== */

/* --- DASH-01: Header --- */
.ps-dash-header {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  padding: 15px 16px;
  background: #121212;
  border-bottom: 1px solid #262626;
}

.ps-dash-logo {
  display: flex;
  align-items: center;
  flex-shrink: 0;
}

/* Phase 69 VIS-01: combined logo SVG (62×20, icon+wordmark with built-in kerning) */
.ps-dash-logo-full {
  width: 62px;
  height: 20px;
  display: block;
}

.ps-dash-user {
  display: flex;
  flex-direction: row;
  gap: 12px;
  align-items: center;
  justify-content: flex-end;
  min-width: 0;
}

.ps-dash-email {
  font-size: 14px;
  font-weight: 400;
  color: rgba(255, 255, 255, 0.6);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 200px;
}

.ps-dash-logout {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  cursor: pointer;
  text-decoration: none;
}

.ps-dash-logout:hover svg path {
  stroke-opacity: 1;
}

/* === Phase 68 PUI-01..04: Figma 3049:1906 / 668:2731 tune-up === */
/* --- DASH-02: Plan Section --- */
.ps-dash-plan-section {
  display: flex;
  flex-direction: column;
  gap: 16px;                 /* Phase 69: Figma 3076:394 — gap between inner block and upgrade button */
  padding: 12px 16px;
  align-items: stretch;      /* Phase 69: was flex-start; allow inner wrapper to take full width */
}

/* Phase 69 VIS-02: Figma 3078:715 — inner wrapper plan-row + progress-bar (constant across tiers) */
.ps-dash-plan-inner {
  display: flex;
  flex-direction: column;
  gap: 14px;
  width: 100%;
}

.ps-dash-plan-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  width: 100%;
}

.ps-dash-col {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.ps-dash-col--right {
  align-items: flex-end;
}

.ps-dash-label {
  font-size: 12px;
  font-weight: 400;
  line-height: 1.3;
  color: var(--ps-popup-muted);
}

.ps-dash-value {
  font-size: 20px;
  font-weight: 400;
  line-height: 1.3;
  color: white;
}

/* --- CREDIT-04: Progress Bar --- */
.ps-dash-bar-track {
  width: 100%;
  height: 6px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 100px;
  overflow: hidden;
}

.ps-dash-bar-fill {
  height: 100%;
  background: white;
  border-radius: 100px;
  transition: width 0.3s ease;
  width: 0%;
}

/* --- DASH-03: Upgrade Button (Free plan) --- */
.ps-dash-upgrade-btn {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 46px;
  padding: 12px 14px;       /* Phase 69: 16→14 horizontal */
  background: white;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-family: 'Inter', sans-serif;
}

.ps-dash-upgrade-btn:hover {
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

.ps-dash-upgrade-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.ps-dash-rocket {
  width: 22px;
  height: 22px;
  flex-shrink: 0;
}

.ps-dash-upgrade-title {
  font-size: 15px;
  font-weight: 600;
  color: #121212;
  white-space: nowrap;
}

.ps-dash-upgrade-sub {
  font-size: 12px;
  font-weight: 500;
  color: #121212;
  text-align: right;
  flex: 1 0 0;
}

/* --- DASH-04/05: Pro/Cancelled Status — Phase 69: 46px dark block (matches Free upgrade-button dimensions) per Figma 3079:1380 */
.ps-dash-pro-status {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.6);
  margin: 0;
  width: 100%;
  height: 46px;
  background: #2e2e2e;
  border-radius: 8px;
  padding: 12px 14px;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  font-family: 'Inter', sans-serif;
}

.ps-dash-sub-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  border: none;
  background: #2e2e2e;       /* Phase 69: same dark underlay so plan-section height stays constant Free↔Pro */
  border-radius: 8px;
  height: 46px;
  padding: 12px 14px;
  box-sizing: border-box;
}

.ps-dash-sub-date {
  font-size: 14px;
  font-weight: 400;
  color: rgba(255, 255, 255, 0.6);
}

.ps-dash-sub-link {
  font-size: 14px;
  font-weight: 400;
  color: rgba(255, 255, 255, 0.6);
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  text-decoration: underline;
  font-family: 'Inter', sans-serif;
}

.ps-dash-sub-link:hover {
  color: rgba(255, 255, 255, 0.9);
}

/* === Phase 45: Instructions + Sites Section === */
.ps-inst-section {
  background: #121212;
  border-top: 1px solid #262626;
  padding: 12px 16px 24px 16px;   /* Phase 69 VIS-02: bot 12→24 — visible 12px gap between item 3 and banner */
  display: flex;
  flex-direction: column;
  gap: 12px;
  height: 236px;                  /* Phase 69 VIS-02: 224→236 (+12 for item3↔banner gap); chat-section mirrors at 318 */
  box-sizing: border-box;
}

.ps-inst-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  position: relative;
}

/* Single dashed line running through all badges */
.ps-inst-list::before {
  content: '';
  position: absolute;
  left: 8px; /* center of 18px badge */
  top: 9px; /* center of first badge */
  bottom: 9px; /* center of last badge */
  width: 0;
  border-left: 1px dashed #363636;
  pointer-events: none;
  z-index: 0;
}

.ps-inst-item {
  display: flex;
  flex-direction: row;
  gap: 8px;
  align-items: flex-start;
  position: relative;
  z-index: 1;
}

.ps-inst-content {
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex: 1;
  min-width: 0;
}

.ps-inst-track {
  flex-shrink: 0;
}

.ps-inst-badge {
  width: 18px;
  height: 18px;
  background: #2A2A2A;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 400;
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-family: 'Inter', sans-serif;
  line-height: 1;
  position: relative;
  z-index: 1;
}

.ps-inst-text {
  font-size: 14px;
  font-weight: 400;
  line-height: 1.3;
  color: rgba(255, 255, 255, 0.6);
  margin: 0;
  padding-top: 0;
  white-space: nowrap;
}

.ps-inst-icon {
  display: inline-block;
  vertical-align: middle;
  width: 14px;
  height: 14px;
  flex-shrink: 0;
  object-fit: contain;
}

/* --- Site Cards (integrated under step 1) --- */
.ps-sites-cards {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: 100%;
}

.ps-site-card {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 10px;
  padding: 8px 12px;
  border-radius: 6px;
  border: 1px solid rgba(0, 0, 0, 0.1);
  cursor: pointer;
  width: 100%;
}

.ps-site-card:hover {
  opacity: 0.9;
}

.ps-site-card--syntx {
  background: #E54717;
  color: white;
}

.ps-site-card--higgsfield {
  background: #D1FE17;
  color: #14151A;
}

.ps-site-card--freepik {
  background: #336AEA;
  color: white;
}

.ps-site-card--freepik .ps-site-card-icon {
  padding: 1.5px;
  box-sizing: border-box;
}

.ps-site-card-icon {
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  display: block;
  overflow: hidden;
}

.ps-site-card-name {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.3;
  flex: 1 0 0;
  min-width: 0;
}

.ps-site-card-status-text {
  font-size: 12px;
  font-weight: 500;
  line-height: 1.3;
  text-align: right;
  white-space: nowrap;
  flex-shrink: 0;
}

.ps-site-status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
}

.ps-site-status-dot--white {
  background: white;
}

.ps-site-status-dot--hidden {
  visibility: hidden;
}

/* === Promo Banner === */
.ps-promo-banner {
  display: block;
  background: #121212;
  padding: 0 16px 12px 16px;    /* Phase 69 VIS-02: Figma 3078:787 — banner total 82px (single source of truth across tiers) */
  text-decoration: none;
  cursor: pointer;
  height: 82px;
  box-sizing: border-box;
}

.ps-promo-banner-inner {
  position: relative;
  width: 388px;
  height: 70px;
  background: #121212;
  border-radius: 8px;
  overflow: hidden;
  isolation: isolate;
  transform: translateZ(0);
}

.ps-promo-banner-bg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  pointer-events: none;
  border-radius: 8px;
}

.ps-promo-banner:hover .ps-promo-banner-inner {
  opacity: 0.95;
}

.ps-promo-banner:focus-visible .ps-promo-banner-inner {
  outline: 2px solid rgba(255, 255, 255, 0.5);
  outline-offset: 2px;
}

/* === Footer === */
.ps-dash-footer {
  background: #121212;
  border-top: 1px solid #262626;
  padding: 10px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.ps-dash-footer-left {
  display: flex;
  align-items: center;
}

.ps-dash-footer-link {
  display: flex;
  align-items: center;
  color: inherit;
  text-decoration: none;
}

.ps-dash-footer-text {
  font-size: 12px;
  font-weight: 400;
  line-height: 1.3;
  color: rgba(255, 255, 255, 0.3);
  white-space: nowrap;
}

/* === Phase 68 TAB-01..03: Popup Tabs (between plan section and inst/chat) === */
.ps-popup-tabs {
  position: relative;
  display: flex;
  gap: 18px;
  height: 40px;
  padding: 0 16px;
  align-items: center;
  background: var(--ps-popup-bg);
  border-top: 1px solid #262626;
  border-bottom: 1px solid #262626;
}

/* Phase 69 D-04 / VIS-04: opacity-based active/inactive (was color-based) */
.ps-popup-tab {
  background: none;
  border: none;
  padding: 0;
  margin: 0;
  font-family: 'Inter', sans-serif;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.3;
  color: #ffffff;                     /* Phase 69 D-04: was rgba(255,255,255,0.6) */
  cursor: pointer;
  position: relative;
  display: inline-flex;               /* Phase 69 D-CD-01: enable icon+text inline layout */
  align-items: center;
  gap: 6px;                           /* Phase 69 D-CD-01: sparkle <-> text spacing */
  opacity: 0.6;                       /* Phase 69 D-04: inactive baseline */
  transition: opacity 0.15s ease;     /* Phase 69 D-CD-03: smooth hover/active */
}

.ps-popup-tab:hover {
  opacity: 0.9;                       /* Phase 69 D-04: was color: rgba(255,255,255,0.9) */
}

.ps-popup-tab--active {
  opacity: 0.9;                       /* Phase 69 D-04: was color: #ffffff */
}

/* :focus-visible — preserved verbatim from Phase 68 (a11y lock) */
.ps-popup-tab:focus-visible {
  outline: 2px solid rgba(255, 255, 255, 0.4);
  outline-offset: 2px;
  border-radius: 4px;
}

/* Phase 69 D-03 / VIS-03: tab sparkle icon — NO filter (SVG is white-fill, dark tab bg wants white).
   NOTE: Different from .ps-chat-improve-icon which DOES use filter:invert(1) for white button bg.
