/* Phase 69 VIS-02: Figma 3083 — gaps (6 above textarea, 8 above improve) */
.ps-chat-section .ps-chat-selectors { margin-bottom: 6px; }
.ps-chat-section .ps-chat-prompt-wrap { margin-bottom: 8px; }

/* === Phase 68 CHAT-02: Type/Model selectors === */
.ps-chat-selectors {
  display: flex;
  gap: 6px;
}

.ps-chat-select {
  flex: 1;
  min-width: 0;             /* permits text-overflow ellipsis (Pitfall 1) */
