}

.ps-chat-copy:not([disabled]) { opacity: 0.6; }
.ps-chat-copy:not([disabled]):hover { opacity: 1; }
.ps-chat-copy[disabled] { cursor: default; }

/* === Phase 68 CHAT-05+CHAT-06: Improve button + sparkle-spin === */
.ps-chat-improve {
  height: 46px;
  width: 100%;
  background: #ffffff;
  color: #000000;
  border: 0;
