}

/* Phase 68 CHAT-06: sparkle flip animation (mirror of content.css ps-stars-flip — used in tooltip improve btn on syntx/etc.) */
.ps-chat-improve--loading .ps-chat-improve-icon {
  animation: ps-popup-sparkle-flip 1s steps(1) infinite;
}

@keyframes ps-popup-sparkle-flip {
  0%   { transform: scaleX(1); }
  50%  { transform: scaleX(-1); }
}

/* === Phase 72 REF-01..04: bottom bar + ref slots + arc-loader === */

/* Phase 72 D-02: hairline divider above bottom bar (Figma 3083:3010 — y=148) */
.ps-chat-prompt-divider {
  position: absolute;
  left: 14px;
  right: 14px;
  top: 148px;
  height: 1px;
  background: #262626;
  pointer-events: none;
}

/* Phase 72 D-02: bottom bar — absolute container inside .ps-chat-prompt-wrap (Figma y=157, height=18) */
.ps-chat-bottom-bar {
  position: absolute;
  left: 14px;
  right: 14px;
  top: 157px;
  height: 18px;
  display: block;
  pointer-events: none;       /* Phase 70 fix: bar overlaps copy-btn area — let clicks pass through to copy-btn */
}

/* Phase 72 D-04: row of ref slots + add button + placeholder */
.ps-chat-refs-row {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 6px;
  height: 18px;
  pointer-events: auto;       /* Phase 70 fix: re-enable clicks on actual interactive content */
}

/* Phase 72 D-07: base ref slot — 18×18 #414141 opacity 0.3 (default = loading-empty look) */
.ps-chat-ref-slot {
  position: relative;
  width: 18px;
  height: 18px;
  border-radius: 3px;
  overflow: hidden;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
