.ps-skill-download:hover:not(:disabled):not(.ps-skill-download--disabled) {
  opacity: 0.9;
}

.ps-skill-download:active:not(:disabled):not(.ps-skill-download--disabled) {
  opacity: 0.8;
}

/* Free state — visually inert grey button, no hover/active animation, no transitions.
   Per user feedback: «неактивной, без анимации и серого цвета». pointer-events:none
   prevents clicks at the CSS layer; psSkillOnDownloadClick has a defense-in-depth guard. */
.ps-skill-download--disabled,
.ps-skill-download:disabled {
  background: #2a2a2a;
  color: rgba(255, 255, 255, 0.4);
  cursor: default;
  pointer-events: none;
  transition: none;
}

.ps-skill-download--disabled:hover,
.ps-skill-download:disabled:hover,
.ps-skill-download--disabled:active,
.ps-skill-download:disabled:active {
  opacity: 1;
  background: #2a2a2a;
  color: rgba(255, 255, 255, 0.4);
}

.ps-skill-download-icon {
  flex-shrink: 0;
  display: block;
}

/* Step 3: Static ChatGPT-style banner mockup (DEC-08..10).
   362x126, rounded 8px, dark bg matching Figma source verbatim. */
.ps-skill-banner {
  position: relative;
  width: 100%;
  max-width: 362px;
  height: 126px;
  background: #0d0d0d;
  border: 1px solid #262626;
  border-radius: 8px;
  margin-top: 8px;
