}

/* Claude logo PNG — 35x35 absolute, top:17px, horizontally centered (Figma 3137:213). */
.ps-skill-banner-logo {
  position: absolute;
  top: 17px;
  left: 50%;
  transform: translateX(-50%);
  width: 35px;
  height: 35px;
  object-fit: contain;
