}

/* Quick 260526-ts9: ChatGPT logo lockup is wide (icon + wordmark, Figma 3242:91 → 117×46),
   unlike Claude's 35×35 square. Overrides width/height/top; inherits centering + object-fit. */
.ps-chatgpt-banner-logo {
  top: 13px;
  width: 117px;
  height: 46px;
}

/* Input pill — 316x37.7, top:68 (was 59.66 — repositioned lower so the
   square Claude logo sits cleanly above), left:23, bg #d9d9d9 opacity 20%. */
.ps-skill-banner-pill {
  position: absolute;
  top: 68px;
  left: 23px;
